function parseCounts(form){
  form=String(form).replace(/[\s·×*]/g,'.');
  var i=0, n=form.length;
  function readFactor(){
    var map={};
    while(i<n){
      var c=form[i];
      if(c==='('){ i++; var g=readFactor();
        var num=1; if(i<n && /[0-9]/.test(form[i])){num=0;while(i<n&&/[0-9]/.test(form[i])){num=num*10+(form[i].charCodeAt(0)-48);i++;}}
        for(var k in g) map[k]=(map[k]||0)+g[k]*num;
        continue;
      }
      if(c===')'){ i++; break; }
      if(c==='.'){ i++;
        var mult=1; if(i<n && /[0-9]/.test(form[i])){mult=0;while(i<n&&/[0-9]/.test(form[i])){mult=mult*10+(form[i].charCodeAt(0)-48);i++;}}
        var rest=readFactor();
        for(var k in rest) map[k]=(map[k]||0)+rest[k]*mult;
        break;
      }
      if(/[A-Z]/.test(c)){
        var sym=c; i++;
        while(i<n && /[a-z]/.test(form[i])){ sym+=form[i]; i++; }
        var cnt=1; if(i<n && /[0-9]/.test(form[i])){cnt=0;while(i<n&&/[0-9]/.test(form[i])){cnt=cnt*10+(form[i].charCodeAt(0)-48);i++;}}
        map[sym]=(map[sym]||0)+cnt;
        continue;
      }
      i++;
    }
    return map;
  }
  return readFactor();
}

function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){var t=b;b=a%b;a=t;}return a||1;}
function lcm(a,b){ if(a===0||b===0) return 0; return Math.abs(a*b)/gcd(a,b); }
function F(n,d){ if(d===undefined)d=1; if(d<0){n=-n;d=-d;} var g=gcd(Math.abs(n),Math.abs(d))||1; return [n/g,d/g]; }
function fadd(a,b){ return F(a[0]*b[1]+b[0]*a[1], a[1]*b[1]); }
function fmul(a,b){ return F(a[0]*b[0], a[1]*b[1]); }
function fneg(a){ return [-a[0],a[1]]; }
function fdiv(a,b){ return F(a[0]*b[1], a[1]*b[0]); }
// 有理数 RREF
function rref(A, cols){
  var M=A.map(function(r){return r.slice();}); var row=0;
  for(var col=0; col<cols && row<M.length; col++){
    var piv=-1; for(var r=row;r<M.length;r++){ if(M[r][col][0]!==0){piv=r;break;} }
    if(piv<0) continue;
    var tmp=M[row];M[row]=M[piv];M[piv]=tmp;
    var pv=M[row][col]; for(var c=0;c<cols;c++) M[row][c]=fdiv(M[row][c],pv);
    for(var r2=0;r2<M.length;r2++){ if(r2===row) continue; var f=M[r2][col]; if(f[0]===0) continue;
      for(var c2=0;c2<cols;c2++) M[r2][c2]=fadd(M[r2][c2], fmul(fneg(f), M[row][c2])); }
    row++;
  }
  return M;
}
function nullBasis(M, cols){
  var R=rref(M, cols); var pivCol=[];
  for(var r=0;r<R.length;r++){ for(var c=0;c<cols;c++){ if(R[r][c][0]===1 && R[r][c][1]===1){ pivCol[r]=c; break; } } }
  var basis=[];
  for(var j=0;j<cols;j++){
    var isFree=true; for(var r=0;r<R.length;r++){ if(pivCol[r]===j){isFree=false;break;} }
    if(!isFree) continue;
    var v=new Array(cols); for(var c=0;c<cols;c++) v[c]=F(0,1);
    v[j]=F(1,1);
    for(var r=0;r<R.length;r++){ if(pivCol[r]!==undefined){ v[pivCol[r]]=fneg(R[r][j]); } }
    basis.push(v);
  }
  return basis;
}
function fracToInts(v){
  var L=1; for(var i=0;i<v.length;i++) L=lcm(L, v[i][1]);
  var ints=[]; for(var i=0;i<v.length;i++) ints.push(v[i][0]*L/v[i][1]);
  // 使首项为正
  var first=0; while(first<ints.length && ints[first]===0) first++;
  if(first<ints.length && ints[first]<0){ for(var i=0;i<ints.length;i++) ints[i]=-ints[i]; }
  var g=0; for(var i=0;i<ints.length;i++) g=gcd(g,Math.abs(ints[i]));
  if(g>1){ for(var i=0;i<ints.length;i++) ints[i]=ints[i]/g; }
  return ints;
}
function balance(eq){
  var sides=eq.split(/\s*(?:->|→|=)\s*/); if(sides.length!==2) return {error:"需写成 A + B -> C + D"};
  function species(s){ return s.split('+').map(function(p){ p=p.replace(/^\s*\d+\s*/,'').trim(); return p; }).filter(Boolean); }
  var R=species(sides[0]), P=species(sides[1]);
  var all=R.concat(P);
  var elemSet={}; all.forEach(function(sp){ var c=parseCounts(sp); for(var k in c) elemSet[k]=1; });
  var elems=Object.keys(elemSet);
  // 矩阵 elems × species；反应物列为 +，产物列为 -
  var M=elems.map(function(e){
    var row=all.map(function(sp){ var c=parseCounts(sp); return F(c[e]||0,1); });
    for(var i=R.length;i<all.length;i++) row[i]=fneg(row[i]);
    return row;
  });
  var basis=nullBasis(M, all.length);
  if(basis.length===0) return {error:"无法配平（可能已配平或矛盾）"};
  var ints;
  if(basis.length===1){ ints=fracToInts(basis[0]); }
  else {
    // 多维零空间：搜索小整数组合使全为正
    var best=null;
    var lim=6;
    (function combine(idx, acc){
      if(idx===basis.length){ var sum=new Array(all.length); for(var i=0;i<all.length;i++) sum[i]=F(0,1);
        for(var k=0;k<acc.length;k++){ for(var i=0;i<all.length;i++) sum[i]=fadd(sum[i], fmul(F(acc[k],1), basis[k][i])); }
        var allPos=true; for(var i=0;i<all.length;i++){ if(sum[i][0]<=0){allPos=false;break;} }
        if(allPos){ var ii=fracToInts(sum); var mx=Math.max.apply(null, ii.map(Math.abs));
          if(!best || mx<best.mx) best={ints:ii, mx:mx}; }
        return;
      }
      for(var w=1;w<=lim;w++){ acc.push(w); combine(idx+1,acc); acc.pop(); }
    })(0,[]);
    if(!best) ints=fracToInts(basis[0]); else ints=best.ints;
  }
  // 组装字符串
  function sideStr(arr, off){ return arr.map(function(sp,i){ var c=ints[off+i]; return (c===1?"":c)+" "+sp; }).join(" + "); }
  return {ok:true, coeffs:ints, text: sideStr(R,0)+" -> "+sideStr(P,R.length)};
}
var EXPORTS={balance:balance, parseCounts:parseCounts};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EquationBalancerForgePure = EXPORTS; }
